SELECT figure_type_id, user_id, figure_type_group_id, name, created_at, updated_at
FROM figure_type
WHERE user_id = #{userId} AND figure_type_id = #{figureTypeId}

SELECT figure_type_id, user_id, figure_type_group_id, name, created_at, updated_at
FROM figure_type
WHERE user_id = #{userId} AND figure_type_group_id = #{figureTypeGroupId} AND name = #{name}

SELECT COUNT(*)
FROM figure_type
WHERE user_id = #{userId} AND figure_type_group_id = #{figureTypeGroupId}

SELECT COUNT(DISTINCT figure_id)
FROM figure
WHERE user_id = #{userId} AND figure_type_id = #{figureTypeId}
